import{_ as a,o,c as t,a2 as r}from"./chunks/framework.BjkiRu3Q.js";const m=JSON.parse('{"title":"Προβλήματα φόρμας και υποβολής κράτησης","description":"","frontmatter":{},"headers":[],"relativePath":"el/help/booking-problems.md","filePath":"el/help/booking-problems.md"}'),l={name:"el/help/booking-problems.md"};function s(i,e,n,h,p,c){return o(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="προβληματα-φορμας-και-υποβολης-κρατησης" tabindex="-1">Προβλήματα φόρμας και υποβολής κράτησης <a class="header-anchor" href="#προβληματα-φορμας-και-υποβολης-κρατησης" aria-label="Permalink to &quot;Προβλήματα φόρμας και υποβολής κράτησης&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Εκπαιδευτικό προσχέδιο βάσει πηγαίου κώδικα · TransferBook+ v0.7.9. Επιβεβαιώστε έκδοση, δικαιώματα και ρυθμίσεις. Χρησιμοποιήστε εγκεκριμένα συνθετικά δεδομένα. Δεν τεκμαίρεται ζωντανή ενεργοποίηση.</p></div><h2 id="η-φορμα-δεν-υποβαλλεται" tabindex="-1">Η φόρμα δεν υποβάλλεται <a class="header-anchor" href="#η-φορμα-δεν-υποβαλλεται" aria-label="Permalink to &quot;Η φόρμα δεν υποβάλλεται&quot;">​</a></h2><p>Ελέγξτε ενεργή περιοχή, κατηγορία οχήματος, χωρητικότητα επιβατών και αποσκευών, έγκυρη ημερομηνία και ώρα, όνομα και τηλέφωνο. Το email είναι προαιρετικό. Επιλέξτε τοποθεσία ή επιβεβαιώστε τη διεύθυνση με <strong>Use custom address</strong>. Οι κανονικές μεταφορές δεν έχουν ίδια αφετηρία και προορισμό.</p><h2 id="η-προσφορα-δεν-εχει-επαληθευτει" tabindex="-1">Η προσφορά δεν έχει επαληθευτεί <a class="header-anchor" href="#η-προσφορα-δεν-εχει-επαληθευτει" aria-label="Permalink to &quot;Η προσφορά δεν έχει επαληθευτεί&quot;">​</a></h2><p>Περιμένετε την τρέχουσα προσφορά του διακομιστή. Αν άλλαξε διαδρομή, κατηγορία, ώρα ή άλλο στοιχείο τιμολόγησης, ελέγξτε τη νέα τιμή πριν την υποβολή. Για μη ρυθμισμένη τιμή ακολουθήστε τη χειροκίνητη προσφορά.</p><h2 id="χαθηκε-η-απαντηση" tabindex="-1">Χάθηκε η απάντηση <a class="header-anchor" href="#χαθηκε-η-απαντηση" aria-label="Permalink to &quot;Χάθηκε η απάντηση&quot;">​</a></h2><p>Αναζητήστε την υπάρχουσα κράτηση και τον κωδικό πριν ξεκινήσετε νέα. Οι πελάτες API διατηρούν το ίδιο κλειδί αιτήματος και αμετάβλητο περιεχόμενο για επανάληψη του ίδιου αιτήματος. Η λήξη χρόνου δεν αποδεικνύει αποτυχία.</p><h2 id="ποτε-ζητατε-βοηθεια" tabindex="-1">Πότε ζητάτε βοήθεια <a class="header-anchor" href="#ποτε-ζητατε-βοηθεια" aria-label="Permalink to &quot;Πότε ζητάτε βοήθεια&quot;">​</a></h2><p>Όταν ένα έγκυρο αίτημα αποτυγχάνει επανειλημμένα, λείπει ρύθμιση ή παραμένει αβέβαιο το αποτέλεσμα. Καταγράψτε το σφάλμα χωρίς ευαίσθητα στοιχεία και την έκδοση.</p><p>Δείτε <a href="/el/plus/create-reservation.html">Δημιουργία κράτησης</a> και <a href="/el/developers/idempotency.html">Ασφαλής επανάληψη</a>.</p>',11)])])}const _=a(l,[["render",s]]);export{m as __pageData,_ as default};
